CREATE TABLE "employment_activation_attempts" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"employee_id" uuid NOT NULL,
	"business_id" uuid NOT NULL,
	"attempt_no" integer NOT NULL,
	"outcome" text NOT NULL,
	"reason" text,
	"detail" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"blocked_by_business_id" uuid,
	"business_date" date NOT NULL,
	"trigger" text NOT NULL,
	"actor_user_id" uuid,
	"command_id" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "employment_activation_attempts_tenant_id" UNIQUE("tenant_id","id"),
	CONSTRAINT "employment_activation_attempts_number" UNIQUE("tenant_id","business_id","attempt_no"),
	CONSTRAINT "employment_activation_attempts_number_positive" CHECK ("employment_activation_attempts"."attempt_no" > 0),
	CONSTRAINT "employment_activation_attempts_outcome" CHECK ("employment_activation_attempts"."outcome" IN ('effective', 'failed', 'suspended')),
	CONSTRAINT "employment_activation_attempts_reason" CHECK (("employment_activation_attempts"."outcome" = 'effective') = ("employment_activation_attempts"."reason" IS NULL)
        AND ("employment_activation_attempts"."outcome" = 'suspended') = ("employment_activation_attempts"."blocked_by_business_id" IS NOT NULL)),
	CONSTRAINT "employment_activation_attempts_trigger" CHECK ("employment_activation_attempts"."trigger" IN ('scheduler', 'retry', 'approval')),
	CONSTRAINT "employment_activation_attempts_detail_object" CHECK (jsonb_typeof("employment_activation_attempts"."detail") = 'object'),
	CONSTRAINT "employment_activation_attempts_command_nonempty" CHECK (btrim("employment_activation_attempts"."command_id") <> '')
);
